const sd=$getWorkflowStaticData('global');
sd.runStartedAt=$now.toMillis();
sd.openRows=[];
sd.campSummary=[];
const cl=$('Get Client').first().json||{};
const cf=cl.fields||cl;
const clientRecId=cl.id||'';
sd.ctx={clientRecId, clientName: cf['Client']||''};
const ws=String(cf['PlusVibe Workspace ID']||'').trim();
const toId=(c)=> typeof c==='string'?c:((c&&c.id)||'');
const out=[];
for(const it of $input.all()){
  const j=it.json||{}; const f=j.fields||j;
  if(!j.id) continue;
  const cl2=Array.isArray(f.Client)?f.Client.map(toId):[];
  if(!cl2.includes(clientRecId)) continue;
  out.push({ json: { campaignRecId: j.id, campaignId: String(f['Campaign ID']||'').trim(), campaignName: f['Campaign']||'', pvWorkspace: ws } });
}
return out.filter(o=>o.json.campaignId);

const sd=$getWorkflowStaticData('global');
const ctx=sd.ctx||{};
const rows=(sd.openRows||[]).slice().sort((a,b)=>b.opens-a.opens);
const now=$now.toISO();
if(!rows.length) return [];
return rows.map(r=>({ json: {
 'Email': r.email,
 'Opens': r.opens,
 'Company': r.company,
 'Campaign': r.campaignRecId?[r.campaignRecId]:[],
 'Client': ctx.clientRecId?[ctx.clientRecId]:[],
 'Replied': r.replied,
 'Status': r.status,
 'MX': r.mx,
 'PV Lead ID': r.leadId,
 'Last Synced': now
}}));

const sd=$getWorkflowStaticData('global');
const rs=sd.runStartedAt||0;
const ctx=sd.ctx||{};
const sum=sd.campSummary||[];
const rows=sd.openRows||[];
let written=0;
try{ written=$('Upsert Openers').all().filter(i=>i&&i.json&&i.json.id).length; }catch(e){}
const lines=sum.map(s=> '- **'+s.campaign+':** '+s.openers+' openers · '+s.sent+' sent · '+s.notSent+' never sent');
const bad = rows.length>0 && written===0;
const descParts=['**'+(ctx.clientName?ctx.clientName+': ':'')+sum.length+' tracked campaign(s), '+rows.length+' openers, '+written+' rows upserted**'];
if(lines.length) descParts.push('**Campaigns**\n'+lines.join('\n'));
if(bad) descParts.push('**NO ROWS WRITTEN**');
const desc=descParts.join('\n\n');
return [{ json: {
 'Automation':'Pull campaign opens for adelante',
 'Status': bad ? 'Failed' : 'Succeeded',
 'Run at': $now.toISO(),
 'Client': ctx.clientRecId ? [ctx.clientRecId] : [],
 'Records In': sum.reduce((s,r)=>s+(r.leads||0),0),
 'Records Out': written,
 'Errors': bad ? 1 : 0,
 'Target': 'Openers table',
 'Trigger':'webhook',
 'Execution ID': String($execution.id),
 'Execution Link': 'https://n8n.flowroots.com/workflow/'+$workflow.id+'/executions/'+$execution.id,
 'Duration s': Math.round(($now.toMillis() - (rs||$now.toMillis()))/1000),
 'Description': desc
}}];

const sd=$getWorkflowStaticData('global');
const cw=$('Loop Campaigns').first().json||{};
const pool=[];
for(const it of $input.all()){ const r=(it&&it.json)||{}; if(Array.isArray(r)){ pool.push(...r); } else if(Array.isArray(r.data)){ pool.push(...r.data); } else if(r.email!==undefined){ pool.push(r); } }
let opened=0, sent=0, notSent=0;
for(const l of pool){
  const st=String(l.status||'').toUpperCase();
  if(!((l.sent_step||0)>0 && st!=='SKIPPED')){ notSent++; continue; }
  sent++;
  const o=Number(l.opened_count||0);
  if(o>0){ opened++; sd.openRows.push({ leadId:String(l._id||l.id||''), email:String(l.email||''), company:String(l.company_name||''), opens:o, replied:Number(l.replied_count||0), status:st, mx:String(l.mx||''), campaignRecId:cw.campaignRecId||'' }); }
}
sd.campSummary.push({ campaign:cw.campaignName||'', leads:pool.length, sent, notSent, openers:opened });
return [{ json: { campaign: cw.campaignName||'', openers: opened } }];
